"""Read verified game assets directly from retained ZIPs without disk extraction."""

# Reading guide: Asset abstraction: ArchivedAsset reads original ZIP members;
# MemoryAsset serves generated bytes with the same interface.
# Editing notes: Resolve logical paths safely and validate indexed ZIP size/CRC before
# use. Keep media archive-backed.
# Checks: offline/test_asset_store.py.
# Project navigation: docs/README.md and docs/05-source-guide.md.

import contextlib, functools, gzip, json, io
from pathlib import Path, PurePosixPath
from types import SimpleNamespace
import zipfile

ROOT = Path(__file__).resolve().parents[1]
INDEX = ROOT / "state/offline/asset-sources.json.gz"


@functools.lru_cache(maxsize=3)
def archive_handle(path):
    """Reuse a bounded number of open ZIP readers."""
    return zipfile.ZipFile(path)


@functools.lru_cache(maxsize=1)
def records():
    """Load the indexed logical-path to archive-member mapping once per process."""
    if not INDEX.is_file():
        return {}
    with gzip.open(INDEX, "rt") as stream:
        return json.load(stream)


class ArchivedAsset:
    """Read-only file-like view of an indexed original ZIP member."""

    def __init__(self, record):
        self.record = record

    def archive(self):
        p = Path(self.record["archive"])
        return p if p.is_absolute() else ROOT / p

    def is_file(self):
        return self.archive().is_file()

    def stat(self):
        return SimpleNamespace(st_size=self.record["size"])

    @contextlib.contextmanager
    def open(self, mode="rb"):
        if mode != "rb":
            raise ValueError("Archived assets are read-only")
        archive = archive_handle(str(self.archive()))
        info = archive.getinfo(self.record["member"])
        if info.file_size != self.record["size"] or info.CRC != self.record["crc"]:
            raise ValueError("Archived asset source changed")
        with archive.open(info) as stream:
            yield stream

    def read_bytes(self):
        with self.open() as stream:
            return stream.read()


class MemoryAsset:
    """Read-only file-like view of generated bytes, with no filesystem extraction."""

    def __init__(self, data):
        self.data = data

    def is_file(self):
        return True

    def stat(self):
        return SimpleNamespace(st_size=len(self.data))

    def open(self, mode="rb"):
        if mode != "rb":
            raise ValueError("Generated manifests are read-only")
        return io.BytesIO(self.data)


def resolve(phase, name, item):
    """Find a manifest-matching ZIP member or safe local content file."""
    logical = PurePosixPath(name)
    if logical.is_absolute() or ".." in logical.parts:
        raise ValueError("Unsafe asset path")
    record = records().get(phase + "/" + name)
    if record and record["size"] == item["size"] and record["md5"] == item["md5"]:
        asset = ArchivedAsset(record)
        if asset.is_file():
            return asset
    base = (ROOT / "contents" / phase).resolve()
    p = (base / name).resolve()
    if base not in p.parents:
        raise ValueError("Unsafe asset path")
    if p.is_file():
        return p
    return None
